tool_calls.command:
# Create a Java program that keeps Saxon running in a loop so we can attach to it
cat > /workspace/saxon-test/SaxonRunner.java << 'JAVAEOF'
import net.sf.saxon.Transform;
import java.io.File;

public class SaxonRunner {
    public static void main(String[] args) throws Exception {
        String saxonJar = "/workspace/saxon/12/Java/saxon-extracted/saxon-he-12.9.jar";
        String libDir = "/workspace/saxon/12/Java/saxon-extracted/lib";

        String[] transformArgs = new String[]{
            "-s:/workspace/saxon-test/large.xml",
            "-xsl:/workspace/saxon-test/complex.xsl",
            "-o:/workspace/saxon-test/runner-output.xml"
        };

        System.out.println("SaxonRunner started. PID: " + ProcessHandle.current().pid());
        System.out.println("Running Saxon transforms in a loop...");

        for (int i = 0; i < 100; i++) {
            long start = System.currentTimeMillis();
            Transform.main(transformArgs);
            long elapsed = System.currentTimeMillis() - start;
            System.out.println("Transform iteration " + i + " completed in " + elapsed + "ms");

            // Keep the JVM alive briefly between transforms
            Thread.sleep(100);
        }

        System.out.println("SaxonRunner completed all iterations.");
    }
}
JAVAEOF

SAXON_JAR=/workspace/saxon/12/Java/saxon-extracted/saxon-he-12.9.jar
SAXON_LIB=/workspace/saxon/12/Java/saxon-extracted/lib

javac -cp "$SAXON_JAR:$SAXON_LIB/*" -d /workspace/saxon-test /workspace/saxon-test/SaxonRunner.java 2>&1
echo "Compiled: $?"

